insert into public.yapilacaklar (baslik, aciklama) select 'Nem normal aralık %50–85, aralık dışı 24 sa (uzman tahmini)', 'Alt destekleyici: Doull 1976 doi:10.1051/apido:19760104 (%50 altında yumurta açılmadı). Üst: kovan için doğrulanmış eşik yok (Flores 1996 %87 kireç artışı, Liang 2000 %80 altı spor çimlenmesi engellendi — destekleyici). Süre kaynaksız.' where not exists (select 1 from public.yapilacaklar y where y.baslik = 'Nem normal aralık %50–85, aralık dışı 24 sa (uzman tahmini)');
